let languageObserver=null;
function isTranslationWordChar(char){return !!char&&/[A-Za-z0-9_\u00C0-\u024F]/.test(char);}
function replaceTranslation(text,from,to){let result="",cursor=0,index;const needsStart=isTranslationWordChar(from[0]),needsEnd=isTranslationWordChar(from[from.length-1]);while((index=text.indexOf(from,cursor))!==-1){const before=text[index-1],after=text[index+from.length],whole=(!needsStart||!isTranslationWordChar(before))&&(!needsEnd||!isTranslationWordChar(after));result+=text.slice(cursor,index)+(whole?to:from);cursor=index+from.length;}return result+text.slice(cursor);}
function localizedText(value){let text=String(value??'');const rows=activeLang==='en'?translations:[...translations].map(([it,en])=>[en,it]);if(activeLang==='en'&&text.startsWith('Confermi l’acquisto di '))text=text.replace('Confermi l’acquisto di ','Confirm purchase of ').replace(' per ',' for ').replace('Il prezzo sarà detratto dal saldo deposito.','The price will be deducted from your deposit balance.');const trimmed=text.trim();const exact=rows.find(([from])=>from===trimmed);if(exact)return text.replace(trimmed,exact[1]);for(const [from,to] of rows.sort((a,b)=>b[0].length-a[0].length)){if(from)text=replaceTranslation(text,from,to);}return text;}
function applyLanguage(){document.documentElement.lang=activeLang;if($('languageSelect'))$('languageSelect').value=activeLang;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement?.closest('#barUser,#helloName,#profileName,.notranslate'))continue;const translated=localizedText(node.nodeValue);if(translated!==node.nodeValue)node.nodeValue=translated;}document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>{for(const attr of ['placeholder','aria-label','title'])if(el.hasAttribute(attr))el.setAttribute(attr,localizedText(el.getAttribute(attr)));});const serverNav=document.querySelector('.nav-item[data-goto="servers"] span:last-child');if(serverNav){const label=t('Server','Servers');if(serverNav.textContent!==label)serverNav.textContent=label;}if($('helloName')){const hello=$('#view-home .hello');if(hello&&hello.firstChild){const greeting=t('Bentornato,','Welcome back,')+' ';if(hello.firstChild.textContent!==greeting)hello.firstChild.textContent=greeting;}}if($('themeToggle')){const label=$('themeToggle').querySelector('span');if(label){const mode=document.body.dataset.theme==='light'?t('Modalità notte','Night mode'):t('Modalità giorno','Day mode');if(label.textContent!==mode)label.textContent=mode;}const icon=document.body.dataset.theme==='light'?'☀':'☾';if($('themeState').textContent!==icon)$('themeState').textContent=icon;}if(languageObserver)languageObserver.takeRecords();}

function setTheme(theme){document.body.dataset.theme=theme;localStorage.setItem('nexa_theme',theme);applyLanguage();if($('settingsTheme'))$('settingsTheme').textContent=theme==='light'?t('Giorno','Day'):t('Notte','Night');}
let currentPlatformPage='settings';function openPlatformPage(kind){currentPlatformPage=kind;const settings=kind==='settings';$('platformHeading').textContent=settings?t('Impostazioni piattaforma','Platform settings'):kind==='about'?t('Chi siamo','About us'):t('Contatti','Contact us');$('platformSubheading').textContent=settings?t('Preferenze del tuo account','Your account preferences'):settings?'':kind==='about'?t('Nexa Compute','Nexa Compute'):t('Scrivici','Get in touch');if(settings){$('platformContent').innerHTML='<div class="settings-card"><span>◈</span><div><b>'+t('Lingua interfaccia','Interface language')+'</b><small>'+t('Scegli la lingua dei controlli principali','Choose the language for the main interface')+'</small></div><select id="settingsLanguage" class="quick-select"><option value="it">Italiano</option><option value="en">English</option></select></div><div class="settings-card"><span>◐</span><div><b>'+t('Aspetto','Appearance')+'</b><small>'+t('Tema chiaro o scuro','Light or dark theme')+'</small></div><button class="btn-mini" id="settingsTheme">'+(document.body.dataset.theme==='light'?t('Giorno','Day'):t('Notte','Night'))+'</button></div><p class="history-note">'+t('Le preferenze vengono salvate su questo dispositivo.','Preferences are saved on this device.')+'</p>';const sel=$('settingsLanguage');sel.value=activeLang;sel.onchange=()=>setLanguage(sel.value);$('settingsTheme').onclick=()=>setTheme(document.body.dataset.theme==='light'?'dark':'light');}else if(kind==='about'){$('platformContent').innerHTML='<div class="about-card"><span class="about-mark">NX</span><h1>Nexa Compute</h1><p>'+t('Una piattaforma per esplorare configurazioni GPU, gestire server acquistati e seguire le attività del tuo account.','A platform to explore GPU configurations, manage purchased servers and follow your account activity.')+'</p><div class="about-rule"></div><small>Versione piattaforma · Nexa Compute</small></div>';}else{$('platformContent').innerHTML='<div class="about-card"><span class="about-mark">✉</span><h1>'+t('Contatta il team','Contact the team')+'</h1><p>'+t('Per assistenza o informazioni, puoi scriverci via email.','For help or information, you can reach us by email.')+'</p><a class="btn-primary contact-link" href="mailto:support@nexacompute.com">'+t('Invia un’email','Send an email')+' →</a></div>';}if($('platformScreen').hidden)showOverlay('platformScreen');}
function prepareMenuNavigation(){ $('quickMenu').hidden=true;$('menuTrigger').setAttribute('aria-expanded','false');if(history.state?.nexaApp&&history.state?.nexaOverlay==='quickMenu')history.replaceState({nexaApp:true,nexaView:currentView},'',location.href);}
function setLanguage(lang){activeLang=lang==='en'?'en':'it';localStorage.setItem('nexa_lang',activeLang);applyLanguage();if(!$('platformScreen').hidden&&currentPlatformPage==='settings')openPlatformPage('settings');if($('appBody')&&!$('appBody').hidden){if(currentView==='catalog')renderCatalog();if(currentView==='servers')renderServers();if(currentView==='home')renderHome();if(currentView==='profile')renderProfile();if(!$('historyScreen').hidden)renderHistory();applyLanguage();}}
$('menuTrigger').addEventListener('click',()=>{const open=$('quickMenu').hidden;$('quickMenu').hidden=!open;$('menuTrigger').setAttribute('aria-expanded',String(open));if(open&&appHistoryReady)history.pushState({nexaApp:true,nexaView:currentView,nexaOverlay:'quickMenu'},'',location.href);else if(!open&&history.state?.nexaOverlay==='quickMenu')history.back();});
document.addEventListener('click',e=>{if(!$('quickMenu').hidden&&!e.target.closest('.appbar-right'))prepareMenuNavigation();});
$('languageSelect').addEventListener('change',e=>setLanguage(e.target.value));$('openInbox').addEventListener('click',()=>{prepareMenuNavigation();showOverlay('inboxScreen');loadInbox().catch(error=>{$('inboxList').innerHTML='<p class="service-note">'+esc(error.message)+'</p>';});});$('closeInbox').addEventListener('click',()=>closeOverlay('inboxScreen'));
let supportPollTimer=null,supportPollBusy=false,inboxUnreadTimer=null;
function supportSeenKey(){return 'nexa_support_seen_'+(state?.user?.id||'');}
function inboxSnapshotKey(){return 'nexa_inbox_snapshot_'+(state?.user?.id||'');}
function inboxBaselineKey(){return 'nexa_inbox_baseline_'+(state?.user?.id||'');}
function inboxEventsKey(){return 'nexa_inbox_events_'+(state?.user?.id||'');}
function readInboxEvents(){try{const rows=JSON.parse(localStorage.getItem(inboxEventsKey())||'[]');return Array.isArray(rows)?rows.map(row=>typeof row==='string'?{key:row,type:'legacy',payload:{},date:Date.now(),unread:true}:row).filter(row=>row&&typeof row.key==='string'):[];}catch{return [];}}
function setInboxMessageBadge(value){const badge=$('inboxMessageBadge'),count=Math.max(0,Number(value)||0);badge.textContent=count>99?'99+':String(count);badge.hidden=count===0;}
function notificationCopy(notification){const item=notification.payload||{},status=(notification.type==='server'?{pending:'In attivazione',active:'Attivo',offline:'Offline'}:{pending:'In attesa',processing:'In elaborazione',approved:'Approvata',rejected:'Rifiutata',code_sent:'Codice inviato',verified:'Verificata',expired:'Scaduta'})[item.status]||item.status||'';if(notification.type==='account'){const title=item.kind==='deposit'?'Richiesta deposito':'Richiesta prelievo';return {title,detail:[status,item.network==='bep20'?'BEP20':item.network==='trc20'?'TRC20':'',item.amount!==undefined?money(item.amount):''].filter(Boolean).join(' · ')};}if(notification.type==='rental'){const product=PRODUCTS.find(p=>p.id===item.product_id)?.name||item.product_id||'';return {title:'Richiesta di noleggio',detail:[product,status].filter(Boolean).join(' · ')};}if(notification.type==='chat')return {title:'Messaggio dell’operatore',detail:String(item.body||'')};if(notification.type==='verification')return {title:'Verifica email',detail:status};if(notification.type==='server'){const product=PRODUCTS.find(p=>p.id===item.product_id)?.name||item.product_id||'';return {title:'Aggiornamento server',detail:[product,status].filter(Boolean).join(' · ')};}return {title:'Notifica',detail:'Aggiornamento precedente'};}
function renderInboxNotifications(){const section=$('inboxNotificationsSection'),container=$('inboxNotifications');if(!section||!container)return;const notices=readInboxEvents().sort((a,b)=>Number(b.date||0)-Number(a.date||0));section.hidden=notices.length===0;container.innerHTML=notices.map(n=>{const copy=notificationCopy(n);const chat=n.type==='chat';return '<article class="inbox-notification '+(n.unread?'unread':'')+'"><div class="inbox-notification-head"><b>'+esc(copy.title)+'</b><time>'+esc(new Date(Number(n.date)||Date.now()).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</time></div><p class="'+(chat?'notranslate':'')+'">'+esc(copy.detail)+'</p><button type="button" class="inbox-notification-delete" data-delete-inbox-notification="'+esc(n.key)+'" aria-label="Elimina notifica">Elimina</button></article>';}).join('');applyLanguage();}
function saveInboxEvents(events){localStorage.setItem(inboxEventsKey(),JSON.stringify(events));setInboxMessageBadge(events.filter(event=>event.unread).length);if(!$('inboxScreen').hidden)renderInboxNotifications();}
function itemSnapshot(items){return Object.fromEntries((items||[]).map(item=>[item.key,String(item.version)]));}
function removeReadChatEvents(latest){const events=readInboxEvents().map(event=>event.key.startsWith('chat:')&&Number(event.key.split(':')[1])<=latest?{...event,unread:false}:event);saveInboxEvents(events);}
function markSupportMessagesRead(messages){const latest=(messages||[]).reduce((max,m)=>Math.max(max,Number(m.id)||0),0);if(latest){const old=Number(localStorage.getItem(supportSeenKey())||0);if(latest>old)localStorage.setItem(supportSeenKey(),String(latest));removeReadChatEvents(latest);}}
function markInboxRead(items){localStorage.setItem(inboxSnapshotKey(),JSON.stringify(itemSnapshot(items)));localStorage.removeItem(inboxBaselineKey());saveInboxEvents(readInboxEvents().map(event=>({...event,unread:false})));const latestChat=(items||[]).filter(item=>item.key.startsWith('chat:')).reduce((max,item)=>Math.max(max,Number(item.id)||0),0);if(latestChat>Number(localStorage.getItem(supportSeenKey())||0))localStorage.setItem(supportSeenKey(),String(latestChat));}
function appendInboxNotification(events,item){const key=item.key+':'+item.version;if(events.some(event=>event.key===key))return;events.push({key,type:item.type||item.key.split(':')[0],payload:item,date:Number(item.occurred_at)||Date.now(),unread:true});}
let inboxUpdateBusy=false;
async function refreshInboxUnread(){if(!state?.user||inboxUpdateBusy)return;inboxUpdateBusy=true;try{const data=await api('/api/inbox/updates'),items=data.items||[],snapshotRaw=localStorage.getItem(inboxSnapshotKey());let events=readInboxEvents(),snapshot={};try{snapshot=snapshotRaw?JSON.parse(snapshotRaw):null;}catch{snapshot=null;}if(!snapshot){const seen=Number(localStorage.getItem(supportSeenKey())||0),baseline=Number(localStorage.getItem(inboxBaselineKey())||Date.now());for(const item of items){if((item.key.startsWith('chat:')&&Number(item.id)>seen)||Number(item.occurred_at||0)>=baseline)appendInboxNotification(events,item);}}else{for(const item of items){const version=String(item.version);if(snapshot[item.key]!==version&&(!item.key.startsWith('chat:')||Number(item.id)>Number(localStorage.getItem(supportSeenKey())||0)))appendInboxNotification(events,item);}}localStorage.setItem(inboxSnapshotKey(),JSON.stringify(itemSnapshot(items)));if(!$('inboxScreen').hidden)events=events.map(event=>({...event,unread:false}));saveInboxEvents(events);}catch{}finally{inboxUpdateBusy=false;}}
function clearChatInboxEvents(){saveInboxEvents(readInboxEvents().map(event=>event.key.startsWith('chat:')?{...event,unread:false}:event));}
document.addEventListener('click',event=>{const button=event.target.closest('[data-delete-inbox-notification]');if(!button)return;const key=button.dataset.deleteInboxNotification;saveInboxEvents(readInboxEvents().filter(item=>item.key!==key));});
function stopInboxUnreadPolling(){if(inboxUnreadTimer){clearInterval(inboxUnreadTimer);inboxUnreadTimer=null;}}
function startInboxUnreadPolling(){stopInboxUnreadPolling();if(!localStorage.getItem(inboxSnapshotKey()))localStorage.setItem(inboxBaselineKey(),String(Date.now()));refreshInboxUnread();inboxUnreadTimer=setInterval(()=>{if(!$('appBody')||$('appBody').hidden||!state?.user){stopInboxUnreadPolling();return;}refreshInboxUnread();},8000);}
function supportDate(value){return new Date(Number(value)||Date.now()).toLocaleString(activeLang==='en'?'en-US':'it-IT');}
function renderSupportMessages(container,messages,adminView=false){const atBottom=container.scrollHeight-container.scrollTop-container.clientHeight<48;container.innerHTML=(messages||[]).map(m=>{const isAgent=m.sender==='admin';return '<article class="support-message '+(isAgent?'agent':'visitor')+'"><small>'+(isAgent?'Operatore':'Tu')+'</small><p class="notranslate">'+esc(m.body)+'</p><time>'+esc(supportDate(m.created_at))+'</time></article>';}).join('')||'<p class="support-empty">'+'Nessun messaggio.'+'</p>';if(atBottom||!messages?.length)container.scrollTop=container.scrollHeight;applyLanguage();}
async function refreshSupportChat(){if(supportPollBusy||$('supportChat').hidden)return;supportPollBusy=true;try{const data=await api('/api/support/messages');renderSupportMessages($('supportChatMessages'),data.messages||[]);$('endSupportConversation').hidden=!(data.messages||[]).length;markSupportMessagesRead(data.messages||[]);}catch(error){$('supportChatError').textContent=localizedText(error.message);}finally{supportPollBusy=false;}}
function stopSupportPolling(){if(supportPollTimer){clearInterval(supportPollTimer);supportPollTimer=null;}}
function startSupportPolling(){stopSupportPolling();refreshSupportChat();supportPollTimer=setInterval(()=>{if($('supportChat').hidden){stopSupportPolling();return;}refreshSupportChat();},3500);}
$('supportLauncher').addEventListener('click',()=>{const panel=$('supportChat');panel.hidden=!panel.hidden;if(panel.hidden)stopSupportPolling();else{ $('supportChatError').textContent='';startSupportPolling();$('supportMessageInput').focus();}});
$('closeSupportChat').addEventListener('click',()=>{$('supportChat').hidden=true;stopSupportPolling();});
$('supportChatForm').addEventListener('submit',async event=>{event.preventDefault();const input=$('supportMessageInput'),button=$('supportSend'),message=input.value.trim();if(!message)return;button.disabled=true;$('supportChatError').textContent='';try{await api('/api/support/messages',{method:'POST',body:JSON.stringify({message})});input.value='';await refreshSupportChat();}catch(error){$('supportChatError').textContent=localizedText(error.message);}finally{button.disabled=false;input.focus();}});
$('endSupportConversation').addEventListener('click',async()=>{if(!confirm(t('Confermi la chiusura definitiva? La cronologia sarà eliminata.','Close this conversation permanently? Its history will be deleted.')))return;const button=$('endSupportConversation');button.disabled=true;$('supportChatError').textContent='';try{await api('/api/support/conversation',{method:'DELETE'});localStorage.setItem(supportSeenKey(),'0');$('supportChatMessages').innerHTML='';$('supportMessageInput').value='';$('endSupportConversation').hidden=true;$('supportChat').hidden=true;stopSupportPolling();clearChatInboxEvents();}catch(error){$('supportChatError').textContent=localizedText(error.message);}finally{button.disabled=false;}});
$('platformSettings').addEventListener('click',()=>{prepareMenuNavigation();openPlatformPage('settings');});$('aboutButton').addEventListener('click',()=>{prepareMenuNavigation();openPlatformPage('about');});$('contactButton').addEventListener('click',()=>{prepareMenuNavigation();openPlatformPage('contact');});$('themeToggle').addEventListener('click',()=>setTheme(document.body.dataset.theme==='light'?'dark':'light'));$('closePlatform').addEventListener('click',()=>closeOverlay('platformScreen'));$('copyPersonalId').addEventListener('click',async()=>{const id=state?.user?.id;if(!id)return;try{await navigator.clipboard.writeText(id);}catch{}$('copyPersonalId').textContent=t('Copiato ✓','Copied ✓');setTimeout(()=>applyLanguage(),1200);});
setTheme(localStorage.getItem('nexa_theme')||'dark');applyLanguage();languageObserver=new MutationObserver(()=>applyLanguage());languageObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
async function refresh(){state=await api('/api/me');return state;}
let currentView='home';let appHistoryReady=false;
function enterApp(){ $('authScreen').hidden=true; $('appBody').hidden=false; renderApp();startInboxUnreadPolling();const restoredView=sessionStorage.getItem('nexa_pull_view');sessionStorage.removeItem('nexa_pull_view');const startView=['home','catalog','servers','invites','profile'].includes(restoredView)?restoredView:'home';if(!appHistoryReady){history.pushState({nexaApp:true,nexaView:startView},'',location.pathname+location.search+'#'+startView);appHistoryReady=true;}go(startView,false);}
function logout(){stopSupportPolling();stopInboxUnreadPolling();$('supportChat').hidden=true;api('/api/logout').catch(()=>{});localStorage.removeItem(TOKEN_KEY);state=null;$('authScreen').hidden=false;$('appBody').hidden=true;$('loginForm').hidden=false;$('registerForm').hidden=true;$('loginId').value='';$('loginPass').value='';hideAuthMsg();resetAuthTabs();}
function go(name,push=true){const target=$('view-'+name);if(!target)return;const changed=name!==currentView;currentView=name;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v===target));document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.goto===name));if(push&&changed&&appHistoryReady)history.pushState({nexaApp:true,nexaView:name},'',location.pathname+location.search+'#'+name);window.scrollTo(0,0);if(name==='home')renderHome();if(name==='catalog')renderCatalog();if(name==='servers')renderServers();if(name==='invites')renderInvites();if(name==='profile')renderProfile();applyLanguage();}
// Pull down at the top of any scrollable screen to reload fresh data; the login token remains in localStorage.
let pullStart=null,pullReloading=false;
window.addEventListener('touchstart',e=>{const scroller=e.target.closest('#historyScreen,#teamScreen,#detailScreen,#platformScreen,#walletScreen,#adminScreen,.admin-table-wrap');const canScrollPage=!$('appBody').hidden||!$('authScreen').hidden||!$('adminScreen').hidden;const top=scroller?scroller.scrollTop<=0:window.scrollY<=0;pullStart=canScrollPage&&top?{y:e.touches[0].clientY,view:currentView}:null;},{passive:true});
window.addEventListener('touchend',e=>{if(!pullStart||pullReloading)return;const distance=e.changedTouches[0].clientY-pullStart.y;const view=pullStart.view;pullStart=null;if(distance<85)return;pullReloading=true;if(!$('appBody').hidden)sessionStorage.setItem('nexa_pull_view',view);location.reload();},{passive:true});

function showOverlay(id,bodyClass='history-open',push=true){const el=$(id);if(!el.hidden)return;el.hidden=false;document.body.classList.add(bodyClass);if(push&&appHistoryReady)history.pushState({nexaApp:true,nexaView:currentView,nexaOverlay:id},'',location.href);}
function closeOverlay(id,bodyClass='history-open'){const el=$(id);el.hidden=true;document.body.classList.remove(bodyClass);if(history.state?.nexaOverlay===id)history.back();}
function hideOverlays(){if(!$('quickMenu').hidden){$('quickMenu').hidden=true;$('menuTrigger').setAttribute('aria-expanded','false');}for(const [id,cls] of [['platformScreen','history-open'],['walletScreen','history-open'],['inboxScreen','history-open'],['teamScreen','history-open'],['historyScreen','history-open'],['emailVerifyScreen','history-open'],['detailScreen','detail-open'],['serverCreditsScreen','history-open']]){if(!$(id).hidden){$(id).hidden=true;document.body.classList.remove(cls);}}}
window.addEventListener('popstate',event=>{if(adminMode||$('appBody').hidden)return;hideOverlays();if(event.state?.nexaApp){go(event.state.nexaView||'home',false);if(event.state.nexaOverlay==='quickMenu'){$('quickMenu').hidden=false;$('menuTrigger').setAttribute('aria-expanded','true');}else if(event.state.nexaOverlay){const cls=event.state.nexaOverlay==='detailScreen'?'detail-open':'history-open';showOverlay(event.state.nexaOverlay,cls,false);}}else{go('home',false);history.pushState({nexaApp:true,nexaView:'home'},'',location.pathname+location.search+'#home');appHistoryReady=true;}});
document.addEventListener('click',event=>{const trigger=event.target.closest('[data-goto]');if(!trigger)return;event.preventDefault();go(trigger.dataset.goto);});
function renderApp(){const user=state.user;$('barUser').textContent=user.username;$('helloName').textContent=user.username;$('profileName').textContent=user.username;$('profileId').textContent='ID personale · '+user.id;[$('appbarAvatar'),$('profileAvatar')].forEach(img=>img.src=avatar(user.username));renderHome();applyLanguage();}
function card(p,compact=false){return '<article class="compute-card detail-card" data-product-detail="'+p.id+'" tabindex="0" aria-label="Dettagli '+p.name+'"><img class="compute-image" src="data:image/jpeg;base64," alt="Server compute" loading="lazy"><div class="compute-top"><span class="compute-tag">'+p.type+'</span><span class="compute-price">'+money(p.price)+'</span></div><h3>'+p.name+'</h3><p>'+p.spec+'</p><div class="daily-yield"><span>Guadagno giornaliero</span><b>'+money(p.daily)+'</b></div><button class="btn-primary purchase-button" data-buy-product="'+p.id+'">Acquista con saldo deposito <span>→</span></button></article>';}
function renderHome(){const deposit=money(state?.wallet?.deposit||0),earnings=money(state?.wallet?.earnings||0);$('homeDepositBalance').textContent=deposit;$('homeWithdrawBalance').textContent=earnings;$('walletDepositBalance').textContent=deposit;$('walletWithdrawBalance').textContent=earnings;}
function renderCatalog(){const groups=['Basic','Media','Elite'];$('catalogDepositBalance').textContent=money(state?.wallet?.deposit||0);$('catalogList').innerHTML=groups.map(tier=>'<section class="tier-section"><div class="tier-head"><span class="eyebrow">FASCIA '+tier.toUpperCase()+'</span><b>4 modelli</b></div><div class="tier-grid">'+PRODUCTS.filter(p=>p.tier===tier).map(p=>card(p)).join('')+'</div></section>').join('');}
async function loadOrders(){const data=await api('/api/rentals');return data.rentals||[];}
async function renderServers(){
  try{const data=await api('/api/servers');await refresh();renderHome();const rows=data.servers||[];$('serverEmpty').hidden=rows.length>0;$('serverList').innerHTML=rows.map(s=>{const p=PRODUCTS.find(x=>x.id===s.product_id)||{name:'Modello',spec:''};const label={active:'Attivo',pending:'In attivazione',offline:'Offline'}[s.status]||s.status;return '<article class="request-card server-card" data-server-detail="'+s.product_id+'" data-server-purchase-id="'+esc(s.purchase_id)+'" data-server-status="'+esc(s.status)+'" data-server-date="'+Number(s.purchased_at)+'" data-server-yield="'+Number(s.total_yield||0)+'" data-server-seconds="'+Number(s.active_seconds||0)+'" tabindex="0" aria-label="Dettagli server '+esc(p.name)+'"><div class="request-head"><div><span class="compute-tag">'+(s.status==='active'?'SERVER ATTIVO':'ATTREZZATURA ACQUISTATA')+'</span><h3>'+esc(p.name)+'</h3></div><span class="request-status '+(s.status==='active'?'status-approved':s.status==='offline'?'status-rejected':'')+'">'+label+'</span></div><p>Prezzo: '+money(s.price)+' · '+esc(p.spec)+'</p><div class="server-yield">Resa cumulata <b>'+money(s.total_yield||0)+'</b></div><small>Acquistato il '+new Date(s.purchased_at).toLocaleString(activeLang==='en'?'en-US':'it-IT')+' · stato aggiornato '+new Date(s.updated_at).toLocaleString(activeLang==='en'?'en-US':'it-IT')+'</small></article>';}).join('');}catch(e){$('serverList').innerHTML='<p class="service-note">Impossibile caricare i server: '+esc(e.message)+'</p>';}
}
function renderInvites(){const code=state?.user?.inviteCode||'';$('inviteCode').textContent=code||'—';const link=code?location.origin+location.pathname+'?invite='+encodeURIComponent(code):'';$('inviteLink').value=link;if(link)QRCode.toCanvas($('inviteQr'),link,{width:150,margin:1,color:{dark:'#10162a',light:'#ffffff'}}).catch(()=>{});}
let historyRecords=[];
const historyTypeName={purchase:'Acquisto',deposit:'Deposito',withdrawal:'Prelievo',credit:'Accredito'};
function renderHistory(){const filter=$('historyFilter').value;const rows=historyRecords.filter(r=>filter==='all'||r.type===filter);$('historyEmpty').hidden=rows.length>0;$('historyList').innerHTML=rows.map(r=>'<article class="history-row"><div><span class="history-type">'+esc(r.label||historyTypeName[r.type])+'</span><small>'+esc(new Date(r.date).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+(r.status?' · '+esc(r.status):'')+(r.details?' · '+esc(r.details):'')+'</small></div><b class="'+(['deposit','credit'].includes(r.type)?'green':'')+'">'+(r.type==='withdrawal'||r.type==='purchase'?'−':'+')+money(r.amount)+'</b></article>').join('');}
async function loadHistory(){
  await refresh();
  const [purchaseData,account,credits]=await Promise.all([api('/api/purchases'),api('/api/account-requests'),api('/api/earning-credits')]);
  const depositBalance=money(state.wallet.deposit), earningsBalance=money(state.wallet.earnings);$('homeDepositBalance').textContent=depositBalance;$('homeWithdrawBalance').textContent=earningsBalance;$('walletDepositBalance').textContent=depositBalance;$('walletWithdrawBalance').textContent=earningsBalance;
  historyRecords=[];
  (state.deposits||[]).forEach(r=>historyRecords.push({type:'deposit',amount:r.amount,date:r.date,label:'Deposito',status:'Approvato'}));
  (state.withdrawals||[]).forEach(r=>historyRecords.push({type:'withdrawal',amount:r.amount,date:r.date,label:'Prelievo',status:'Approvato'}));
  (purchaseData.purchases||[]).forEach(r=>historyRecords.push({type:'purchase',amount:r.price,date:r.purchased_at,label:'Acquisto attrezzatura',status:'Completato'}));
  (credits.credits||[]).filter(r=>r.earning_type!=='server').forEach(r=>historyRecords.push({type:'credit',amount:r.amount,date:r.created_at,label:'Accredito registrato',status:'Accreditato'}));
  (account.requests||[]).filter(r=>r.status!=='approved').forEach(r=>historyRecords.push({type:r.kind==='deposit'?'deposit':'withdrawal',amount:r.amount,date:r.created_at,label:(r.kind==='deposit'?'Richiesta deposito':'Richiesta prelievo')+(r.network?' · '+(r.network==='bep20'?'BEP20':'TRC20'):''),details:r.tx_hash||r.withdrawal_address||'',status:{pending:'In attesa',rejected:'Rifiutata',processing:'In elaborazione'}[r.status]||r.status}));
  historyRecords.sort((a,b)=>b.date-a.date);renderHistory();
}
async function loadInbox(){
  $('inboxList').innerHTML='<p class="service-note">Caricamento…</p>';
  const [accountData,rentalData]=await Promise.all([api('/api/account-requests'),api('/api/rentals')]);try{const updates=await api('/api/inbox/updates');markInboxRead(updates.items||[]);}catch{renderInboxNotifications();}
  const requests=[...(accountData.requests||[]).map(r=>({...r,requestType:r.kind==='deposit'?'Richiesta deposito':'Richiesta prelievo'})),...(rentalData.rentals||[]).map(r=>({...r,requestType:'Richiesta di noleggio',productName:PRODUCTS.find(p=>p.id===r.product_id)?.name||r.product_id}))].sort((a,b)=>Number(b.created_at||0)-Number(a.created_at||0));
  const statusLabel={pending:'In attesa',processing:'In elaborazione',approved:'Approvata',rejected:'Rifiutata'};
  $('inboxEmpty').hidden=requests.length>0;
  $('inboxList').innerHTML=requests.map(r=>{const status=r.status||'pending';const extra=r.productName||([r.network==='bep20'?'BEP20':r.network==='trc20'?'TRC20':''].filter(Boolean).join(' · '));const amount=Number.isFinite(Number(r.amount))&&r.amount!==undefined?'<b>'+esc(money(r.amount))+'</b>':'';return '<article class="wallet-request-card"><div class="wallet-request-top"><span>'+esc(r.requestType)+'</span><span class="request-status '+(status==='approved'?'status-approved':status==='rejected'?'status-rejected':'')+'">'+esc(statusLabel[status]||status)+'</span></div><div class="wallet-request-bottom">'+amount+'<time>'+esc(new Date(r.created_at).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</time></div>'+(extra?'<small class="wallet-request-detail">'+esc(extra)+'</small>':'')+'</article>';}).join('');
  applyLanguage();
}
function openHistory(){ showOverlay('historyScreen');loadHistory().catch(e=>{$('historyList').innerHTML='<p class="service-note">'+esc(e.message)+'</p>';}); }
$('openHistory').addEventListener('click',openHistory);
$('closeHistory').addEventListener('click',()=>closeOverlay('historyScreen'));
async function updateDepositAddress(){const result=await api('/api/deposit-addresses');const address=result.addresses?.[$('depositNetwork').value]||'';$('depositAddress').value=address;if(!address)throw new Error('Indirizzo di deposito non configurato per questa rete.');}
$('openWallet').addEventListener('click',()=>{showOverlay('walletScreen');$('walletHub').hidden=false;$('depositRequestSection').hidden=true;$('withdrawalRequestSection').hidden=true;$('depositMessage').textContent='';$('withdrawalMessage').textContent='';$('withdrawAddressMessage').textContent='';const saved=state?.acc?.withdraw_wallets||{};$('withdrawAddressInput').value=saved[$('withdrawNetwork').value]||'';$('depositDetails').hidden=true;$('depositTxHash').value='';$('depositAmount').value='';$('withdrawalAmount').value='';document.querySelector('[data-account-request="deposit"]').textContent='Richiedi deposito';});
$('openDepositSection').addEventListener('click',()=>{$('walletHub').hidden=true;$('depositRequestSection').hidden=false;$('withdrawalRequestSection').hidden=true;});
$('openWithdrawalSection').addEventListener('click',()=>{$('walletHub').hidden=true;$('depositRequestSection').hidden=true;$('withdrawalRequestSection').hidden=false;});
$('backFromDeposit').addEventListener('click',()=>{$('depositRequestSection').hidden=true;$('walletHub').hidden=false;});
$('backFromWithdrawal').addEventListener('click',()=>{$('withdrawalRequestSection').hidden=true;$('walletHub').hidden=false;});
$('closeWallet').addEventListener('click',()=>closeOverlay('walletScreen'));
$('withdrawNetwork').addEventListener('change',()=>{$('withdrawAddressInput').value=(state?.acc?.withdraw_wallets||{})[$('withdrawNetwork').value]||'';});
$('depositNetwork').addEventListener('change',async()=>{if(!$('depositDetails').hidden){$('depositTxHash').value='';try{await updateDepositAddress();}catch(e){$('depositMessage').textContent=e.message;}}});
$('copyDepositAddress').addEventListener('click',async()=>{const value=$('depositAddress').value;if(!value)return;try{await navigator.clipboard.writeText(value);$('depositMessage').textContent='Indirizzo copiato.';}catch{$('depositAddress').select();document.execCommand('copy');$('depositMessage').textContent='Indirizzo copiato.';}});
$('saveWithdrawAddress').addEventListener('click',async()=>{const network=$('withdrawNetwork').value,address=$('withdrawAddressInput').value.trim();if(!address){$('withdrawAddressInput').focus();return;}const wallets={...(state?.acc?.withdraw_wallets||{}),[network]:address};const button=$('saveWithdrawAddress');button.disabled=true;try{const result=await api('/api/save-wallet',{method:'POST',body:JSON.stringify({wallets})});state.acc={...(state.acc||{}),...result.acc};$('withdrawAddressMessage').textContent='Indirizzo associato.';}catch(error){$('withdrawAddressMessage').textContent=error.message;}finally{button.disabled=false;}});

let teamMembersCache=[];
function openReferralEarnings(member){$('detailHeading').textContent=t('Guadagni ·','Earnings ·')+member.username;$('detailSubheading').textContent=t('Dettaglio commissioni dell’invitato','Referral earnings breakdown');$('detailContent').innerHTML='<div class="detail-hero"><span class="compute-tag">'+t('INVITATO · LIVELLO','INVITED · LEVEL')+' '+esc(member.level)+'</span><h1>'+esc(member.username)+'</h1><p>Riepilogo dei guadagni registrati e delle commissioni generate da questo invitato.</p></div><div class="detail-stat-grid">'+detailStat('Guadagni registrati dell’invitato',money(member.earnings))+detailStat('Commissioni sui guadagni',money(member.earningsCommission))+detailStat('Primo deposito',money(member.firstDeposit))+detailStat('Bonus primo deposito',money(member.firstDepositBonus))+detailStat('Totale commissioni da invitato',money(member.commission))+detailStat('Livello',esc(member.level))+'</div><p class="history-note">Iscritto il '+esc(new Date(member.joined).toLocaleDateString(activeLang==='en'?'en-US':'it-IT'))+'</p>';showOverlay('detailScreen','detail-open');}
async function openTeam(){ showOverlay('teamScreen');$('teamList').innerHTML='<p class="service-note">Caricamento team…</p>';try{const data=await api('/api/team');await refresh();renderHome();const members=data.members||[];teamMembersCache=members;const total=members.reduce((sum,m)=>sum+Number(m.commission||0),0);$('teamEmpty').hidden=members.length>0;$('teamSummary').innerHTML='<div class="team-total"><span>Commissioni accreditate del team</span><b>'+money(total)+'</b></div>'+[1,2,3].map(level=>'<div class="team-level"><span>Livello '+['','A','B','C'][level]+' · '+members.filter(m=>m.level===level).length+' invitati</span><b>'+money(members.filter(m=>m.level===level).reduce((sum,m)=>sum+Number(m.commission||0),0))+'</b></div>').join('');$('teamList').innerHTML=members.map((m,index)=>'<article class="team-member"><div class="team-member-top"><div><span class="team-badge">'+['','A','B','C'][m.level]+' · L'+m.level+'</span><button type="button" class="team-name-link" data-referral-member="'+index+'">'+esc(m.username)+'</button></div><b class="green">'+money(m.commission)+'</b></div><small>Iscritto il '+esc(new Date(m.joined).toLocaleDateString(activeLang==='en'?'en-US':'it-IT'))+' · guadagni registrati '+money(m.earnings)+'</small><div class="team-breakdown"><span>Commissione '+[0,5,3,1][m.level]+'%: '+money(m.earningsCommission)+'</span>'+(m.level===1?'<span>Bonus primo deposito (5%): '+money(m.firstDepositBonus)+'</span>':'')+'</div></article>').join('');if(!members.length)$('teamList').innerHTML='';}catch(e){$('teamList').innerHTML='<p class="service-note">'+esc(e.message)+'</p>';}}
$('openTeam').addEventListener('click',openTeam);
$('closeTeam').addEventListener('click',()=>closeOverlay('teamScreen'));


function detailStat(label,value,note=''){return '<div class="detail-stat"><span>'+label+'</span><b>'+value+'</b>'+(note?'<small>'+note+'</small>':'')+'</div>';}
function trendMarkup(daily){const factors=[.73,.88,.81,1.02,.94,1.12,1.08];return '<div class="trend-chart">'+factors.map((factor,i)=>{const v=daily*factor;const pct=Math.max(12,Math.round(factor/1.15*100));return '<div class="trend-column"><b>'+money(v)+'</b><span class="trend-bar" style="height:'+pct+'%"></span><small>'+(activeLang==='en'?['−6d','−5d','−4d','−3d','−2d','Yesterday','Today']:['−6g','−5g','−4g','−3g','−2g','Ieri','Oggi'])[i]+'</small></div>';}).join('')+'</div>';}
function openEquipmentDetail(productId, server=null){const p=PRODUCTS.find(item=>item.id===productId);if(!p)return;const hw=HARDWARE[p.id];const isServer=!!server;const activeSeconds=isServer?Number(server.activeSeconds||0):0;const serverYield=isServer?Number(server.totalYield||0):0;const energyKwh=hw.power/1000*activeSeconds/3600;const fullDayKwh=hw.power/1000*24;const statusLabel={active:'Attivo',pending:'In attivazione',offline:'Offline'}[server?.status]||'Catalogo';$('detailHeading').textContent=isServer?p.name+' · server':p.name;$('detailSubheading').textContent=isServer?'Dati e resa di questa attrezzatura':'Scheda tecnica e profilo di utilizzo';$('detailContent').innerHTML='<div class="detail-hero"><span class="compute-tag">'+(isServer?'SERVER PERSONALE':'SCHEDA CATALOGO')+'</span><h1>'+esc(p.name)+'</h1><p>'+esc(p.spec)+'</p></div>'+(isServer?'<div class="server-detail-status"><span>Stato</span><b>'+esc(statusLabel)+'</b></div>':'')+'<div class="detail-stat-grid">'+detailStat('GPU NVIDIA',esc(hw.gpu))+detailStat('Memoria GPU',esc(hw.vram))+detailStat('Potenza',hw.power+' W')+detailStat(isServer?'Consumo accumulato':'Consumo / 24 ore',isServer?energyKwh.toFixed(2)+' kWh':fullDayKwh.toFixed(1)+' kWh',isServer?(activeSeconds/3600).toFixed(1)+' ore attivo':(fullDayKwh*30).toFixed(0)+' kWh / 30 giorni')+'</div><section class="detail-section"><h2>Utilizzi consigliati</h2><p>'+esc(hw.workload)+'</p></section><section class="detail-section"><div class="detail-section-head"><h2>'+(isServer?'Andamento':'Resa giornaliera')+'</h2><b>'+money(p.daily)+' / giorno</b></div><div class="detail-chart-labels"><span>Ultimi 7 giorni</span></div>'+trendMarkup(p.daily)+'</section><div class="detail-stat-grid detail-output">'+detailStat(isServer?'Resa cumulata':'Resa mensile',isServer?money(serverYield):money(p.daily*30),isServer?'In base al tempo attivo':'')+detailStat(isServer?'Tempo attivo':'Prezzo',isServer?(activeSeconds/3600).toFixed(1)+' ore':money(p.price),'')+'</div>'+(isServer?'<button class="btn-primary server-credits-open" data-server-credits="'+esc(server.purchaseId||'')+'">'+t('Visualizza accrediti di questo server','View credits for this server')+' →</button>':'<button class="btn-primary detail-buy" data-buy-product="'+p.id+'">Acquista con saldo deposito · '+money(p.price)+' →</button>');showOverlay('detailScreen','detail-open');}
document.addEventListener('click',e=>{const server=e.target.closest('[data-server-detail]');if(server){openEquipmentDetail(server.dataset.serverDetail,{purchaseId:server.dataset.serverPurchaseId,status:server.dataset.serverStatus,date:Number(server.dataset.serverDate),totalYield:Number(server.dataset.serverYield),activeSeconds:Number(server.dataset.serverSeconds)});return;}const product=e.target.closest('[data-product-detail]');if(product&&!e.target.closest('button'))openEquipmentDetail(product.dataset.productDetail);});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-product-detail],[data-server-detail]')){e.preventDefault();const el=e.target;if(el.dataset.serverDetail)openEquipmentDetail(el.dataset.serverDetail,{purchaseId:el.dataset.serverPurchaseId,status:el.dataset.serverStatus,date:Number(el.dataset.serverDate),totalYield:Number(el.dataset.serverYield),activeSeconds:Number(el.dataset.serverSeconds)});else openEquipmentDetail(el.dataset.productDetail);}});
$('closeDetail').addEventListener('click',()=>closeOverlay('detailScreen','detail-open'));
$('closeServerCredits').addEventListener('click',()=>closeOverlay('serverCreditsScreen'));
async function openServerCredits(purchaseId){if(!purchaseId)return;$('serverCreditsHeading').textContent=t('Accrediti server','Server credits');$('serverCreditsSubheading').textContent=t('Movimenti di questo server','Activity for this server');$('serverCreditsContent').innerHTML='<p class="service-note">Caricamento accrediti…</p>';showOverlay('serverCreditsScreen');try{const data=await api('/api/server-credits?purchase_id='+encodeURIComponent(purchaseId));const product=PRODUCTS.find(p=>p.id===data.product_id);$('serverCreditsHeading').textContent=t('Accrediti ·','Credits ·')+' '+(product?.name||'server');const rows=(data.credits||[]).map(row=>'<article class="history-row"><div><span class="history-type">Accredito server</span><small>'+esc(new Date(Number(row.created_at)).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</small></div><b class="green">+'+money(row.amount)+'</b></article>');if(Number(data.unassigned_legacy)>0)rows.unshift('<article class="history-row"><div><span class="history-type">Accrediti precedenti</span><small>Totale storico già registrato per questo server</small></div><b class="green">+'+money(data.unassigned_legacy)+'</b></article>');$('serverCreditsContent').innerHTML='<div class="server-credit-total"><span>Totale accreditato da questo server</span><b>'+money(data.credited_total)+'</b></div>'+(rows.join('')||'<div class="empty"><span>◌</span><p>Nessun accredito registrato per questo server.</p></div>');}catch(error){$('serverCreditsContent').innerHTML='<p class="service-note">'+esc(error.message)+'</p>';}}
document.addEventListener('click',e=>{const credit=e.target.closest('[data-server-credits]');if(credit){openServerCredits(credit.dataset.serverCredits);return;}const referral=e.target.closest('[data-referral-member]');if(referral){const member=teamMembersCache[Number(referral.dataset.referralMember)];if(member)openReferralEarnings(member);}});

$('historyFilter').addEventListener('change',renderHistory);
$('copyInviteLink').addEventListener('click',async()=>{const value=$('inviteLink').value;if(!value)return;try{await navigator.clipboard.writeText(value);}catch{$('inviteLink').select();document.execCommand('copy');}const b=$('copyInviteLink');b.textContent='Copiato ✓';setTimeout(()=>b.textContent='Copia link',1400);});
function renderProfile(){document.querySelectorAll('.acc-row').forEach(row=>row.onclick=()=>{const p=$(row.dataset.panel);p.hidden=!p.hidden;row.classList.toggle('open',!p.hidden);});$('emailVerificationSummary').textContent=state?.user?.email_verified?'Email verificata ✓':'Conferma il tuo indirizzo email';}
async function loadEmailVerification(){const msg=$('emailVerifyMessage');msg.textContent='';$('emailOtpEntry').hidden=true;try{const data=await api('/api/email-verification');if(state?.user)state.user.email_verified=!!data.verified;$('emailVerificationSummary').textContent=data.verified?'Email verificata ✓':'Conferma il tuo indirizzo email';if(data.email)$('verifyEmailInput').value=data.email;if(data.verified){msg.textContent='Questo indirizzo email è già verificato.';$('emailOtpEntry').hidden=true;}else if(data.status==='pending'){$('emailOtpEntry').hidden=false;msg.textContent='Richiesta inviata. In attesa dell’email con il codice OTP.';}else if(data.status==='code_sent'){$('emailOtpEntry').hidden=false;msg.textContent='Codice inviato dall’amministratore. Inseriscilo qui per completare la verifica.';}else if(data.status==='expired'){msg.textContent='Il codice è scaduto o i tentativi sono esauriti. Invia una nuova richiesta.';}}catch(error){msg.textContent=error.message;}}
$('openEmailVerification').addEventListener('click',()=>{showOverlay('emailVerifyScreen');$('verifyEmailInput').value=state?.user?.identifier?.includes('@')?state.user.identifier:'';loadEmailVerification();});$('closeEmailVerification').addEventListener('click',()=>closeOverlay('emailVerifyScreen'));
$('requestEmailOtp').addEventListener('click',async()=>{const button=$('requestEmailOtp'),msg=$('emailVerifyMessage'),email=$('verifyEmailInput').value.trim();msg.textContent='';if(!email){$('verifyEmailInput').focus();msg.textContent='Inserisci il tuo indirizzo email.';return;}button.disabled=true;try{await api('/api/email-verification/request',{method:'POST',body:JSON.stringify({email})});await loadEmailVerification();}catch(error){msg.textContent=error.message;}finally{button.disabled=false;}});
$('submitEmailOtp').addEventListener('click',async()=>{const button=$('submitEmailOtp'),msg=$('emailVerifyMessage'),code=$('verifyOtpInput').value.trim();msg.textContent='';if(!/^\d{6}$/.test(code)){msg.textContent='Inserisci il codice OTP di 6 cifre.';return;}button.disabled=true;try{await api('/api/email-verification/verify',{method:'POST',body:JSON.stringify({code})});$('verifyOtpInput').value='';await refresh();renderProfile();await loadEmailVerification();}catch(error){msg.textContent=error.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{const btn=e.target.closest('.rent-request');if(!btn)return;const product_id=btn.dataset.product;btn.disabled=true;try{await api('/api/rentals',{method:'POST',body:JSON.stringify({product_id})});alert(localizedText('Richiesta registrata. La disponibilità e i dettagli saranno confermati prima di qualsiasi attivazione o addebito.'));renderHome();}catch(err){alert(err.message);}finally{btn.disabled=false;}});
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-buy-product]');if(!btn)return;const p=PRODUCTS.find(x=>x.id===btn.dataset.buyProduct);if(!p)return;if(p.price>Number(state?.wallet?.deposit||0)){alert(localizedText('Saldo deposito insufficiente per acquistare '+p.name+'.'));return;}if(!confirm(localizedText('Confermi l’acquisto di '+p.name+' per '+money(p.price)+'? Il prezzo sarà detratto dal saldo deposito.')))return;btn.disabled=true;try{await api('/api/purchases',{method:'POST',body:JSON.stringify({product_id:p.id})});await refresh();renderCatalog();await renderServers();renderHome();alert(localizedText('Acquisto registrato. Saldo deposito aggiornato.'));}catch(err){alert(err.message);}finally{btn.disabled=false;}});
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-account-request]');if(!btn)return;const kind=btn.dataset.accountRequest;const amountInput=$(kind==='deposit'?'depositAmount':'withdrawalAmount');const message=$(kind==='deposit'?'depositMessage':'withdrawalMessage');const amount=Number(amountInput.value);if(!Number.isFinite(amount)||amount<=0){amountInput.focus();return;}if(kind==='deposit'&&$('depositDetails').hidden){try{await updateDepositAddress();$('depositDetails').hidden=false;$('depositMessage').textContent='Copia l’indirizzo, effettua il pagamento e poi inserisci il TXHash.';btn.textContent='Invia richiesta deposito';}catch(error){$('depositMessage').textContent=error.message;}return;}const network=kind==='deposit'?$('depositNetwork').value:$('withdrawNetwork').value;const tx_hash=kind==='deposit'?$('depositTxHash').value.trim():'';if(kind==='deposit'&&!tx_hash){$('depositTxHash').focus();$('depositMessage').textContent='Inserisci il TXHash dopo aver effettuato il pagamento.';return;}if(kind==='withdrawal'&&!(state?.acc?.withdraw_wallets||{})[network]){$('withdrawAddressMessage').textContent='Associa prima un indirizzo di prelievo per questa rete.';$('withdrawAddressInput').focus();return;}btn.disabled=true;try{await api('/api/account-requests',{method:'POST',body:JSON.stringify({kind,amount,network,tx_hash})});amountInput.value='';if(kind==='deposit'){$('depositTxHash').value='';$('depositDetails').hidden=true;document.querySelector('[data-account-request="deposit"]').textContent='Richiedi deposito';}$('depositMessage').textContent='';message.textContent='Richiesta registrata: resta in attesa di revisione.';await loadHistory();renderHome();}catch(err){message.textContent=err.message;}finally{btn.disabled=false;}});
$('pwSave').addEventListener('click',async()=>{const current=$('pwCur').value,next=$('pwNew').value,next2=$('pwNew2').value,msg=$('pwMsg');msg.textContent='';if(!current||!next){msg.textContent='Compila tutti i campi.';msg.style.color='var(--red)';return;}if(next.length<6){msg.textContent='La nuova password deve avere almeno 6 caratteri.';msg.style.color='var(--red)';return;}if(next!==next2){msg.textContent='Le password non coincidono.';msg.style.color='var(--red)';return;}try{await api('/api/change-password',{method:'POST',body:JSON.stringify({current,next})});$('pwCur').value='';$('pwNew').value='';$('pwNew2').value='';msg.textContent='Password aggiornata.';msg.style.color='var(--green)';}catch(err){msg.textContent=err.message;msg.style.color='var(--red)';}});
// ---------- Auth (registrazione / login) ----------
function hideAuthMsg() { const m = $('authMsg'); m.hidden = true; m.textContent = ''; }
function resetAuthTabs() {
  hideAuthMsg();
  $('tabLogin').classList.add('active');
  $('tabRegister').classList.remove('active');
  $('loginForm').hidden = false;
  $('registerForm').hidden = true;
}
$('tabLogin').addEventListener('click', resetAuthTabs);
$('tabRegister').addEventListener('click', () => {
  hideAuthMsg();
  $('tabLogin').classList.remove('active');
  $('tabRegister').classList.add('active');
  $('loginForm').hidden = true;
  $('registerForm').hidden = false;
});

// Registrazione: crea l'account, poi si accede solo con le credenziali
$('registerForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const id = $('regId').value.trim();
  const username = $('regUser').value.trim();
  const pass = $('regPass').value;
  const invite = $('regInvite').value.trim();
  $('regErr').textContent = '';
  if (!id || !username || !pass) { $('regErr').textContent = 'Compila tutti i campi.'; return; }
  if (pass.length < 6) { $('regErr').textContent = 'Password di almeno 6 caratteri.'; return; }
  if (pass !== $('regPass2').value) { $('regErr').textContent = 'Le password non coincidono.'; return; }
  try {
    await api('/api/register', { method: 'POST', body: JSON.stringify({ identifier: id, username, password: pass, invite }) });
    $('registerForm').reset();
    $('tabRegister').classList.remove('active');
    $('tabLogin').classList.add('active');
    $('registerForm').hidden = true;
    $('loginForm').hidden = false;
    $('loginId').value = id;
    $('loginPass').value = '';
    $('loginErr').textContent = '';
    const m = $('authMsg');
    m.textContent = '✅ Account creato! Ora accedi con le tue credenziali.';
    m.hidden = false;
  } catch (err) { $('regErr').textContent = err.message; }
});

// Login: solo credenziali
$('loginForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const id = $('loginId').value.trim();
  const pass = $('loginPass').value;
  $('loginErr').textContent = '';
  if (!id || !pass) { $('loginErr').textContent = 'Inserisci email/telefono e password.'; return; }
  try {
    const res = await api('/api/login', { method: 'POST', body: JSON.stringify({ id, password: pass }) });
    token = res.token;
    localStorage.setItem(TOKEN_KEY, token);
    await refresh();
    enterApp();
  } catch (err) { $('loginErr').textContent = err.message; }
});

// Logout (i dati restano salvati, mai cancellati)
$('logoutBtn').addEventListener('click', () => logout());


const ADMIN_VIEW_KEY='nexa_admin_owner_view';
const adminMode=new URLSearchParams(location.search).get('admin')==='1';
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const adminMoney=n=>new Intl.NumberFormat(activeLang==='en'?'en-US':'it-IT',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(n)||0);
async function adminApi(path,opts={}){const headers={...(opts.headers||{})};if(opts.body)headers['content-type']='application/json';const res=await fetch(path,{...opts,headers});let body={};try{body=await res.json();}catch{}if(!res.ok)throw new Error(body.error||'Errore server.');return body;}
function activateAdminSection(section){const pages=document.querySelectorAll('.admin-page[data-admin-page]');let activePage=null;pages.forEach(page=>{const active=page.dataset.adminPage===section;page.hidden=!active;page.classList.toggle('active',active);if(active)activePage=page;});if(!activePage)return;document.querySelectorAll('.admin-nav-item[data-admin-section]').forEach(button=>{const active=button.dataset.adminSection===section;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});const main=$('adminMain');if(main)main.scrollTop=0;}
document.addEventListener('click',event=>{const button=event.target.closest('.admin-nav-item[data-admin-section]');if(button)activateAdminSection(button.dataset.adminSection);});
let adminRequestTimer=null,adminRequestBusy=false;
function stopAdminRequestPolling(){if(adminRequestTimer){clearInterval(adminRequestTimer);adminRequestTimer=null;}}
async function refreshAdminRequestBadges(){if(adminRequestBusy||$('adminDashboard').hidden)return;adminRequestBusy=true;try{const response=await adminApi('/api/admin/request-counts'),raw=response.counts||{},counts={support:Number(raw.support)||0,verification:Number(raw.emailVerifications)||0,depositRequests:Number(raw.depositRequests)||0,withdrawalRequests:Number(raw.withdrawalRequests)||0,servers:Number(raw.servers)||0,computeRequests:Number(raw.computeRequests)||0};let total=0;for(const [key,value] of Object.entries(counts)){const count=Math.max(0,value);total+=count;const badge=document.querySelector('[data-admin-badge="'+key+'"]');if(badge){badge.textContent=count>99?'99+':String(count);badge.hidden=count===0;}}const totalBadge=$('adminTotalBadge');if(totalBadge){totalBadge.textContent=total>99?'99+':String(total);totalBadge.hidden=total===0;}const summary=document.querySelector('.admin-alert-summary');if(summary)summary.classList.toggle('has-alert',total>0);}catch(error){if(error.message.includes('proprietario')){stopAdminRequestPolling();localStorage.removeItem(ADMIN_VIEW_KEY);showAdminLogin(error.message);}}finally{adminRequestBusy=false;}}
function startAdminRequestPolling(){stopAdminRequestPolling();refreshAdminRequestBadges();adminRequestTimer=setInterval(()=>{if($('adminDashboard').hidden){stopAdminRequestPolling();return;}refreshAdminRequestBadges();},30000);}
function showAdminLogin(message=''){ stopAdminSupportPolling();stopAdminRequestPolling();$('adminLoginView').hidden=false;$('adminDashboard').hidden=true;$('adminScreen').hidden=false;$('authScreen').hidden=true;$('appBody').hidden=true;$('adminError').textContent=message; }
let adminSupportTimer=null,adminSupportBusy=false,activeSupportAccount='';
function supportAdminMessageMarkup(messages){const box=$('adminChatMessages'),atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<48;box.innerHTML=(messages||[]).map(m=>{const agent=m.sender==='admin';return '<article class="support-message '+(agent?'agent':'visitor')+'"><small>'+(agent?'Operatore':'Utente')+'</small><p class="notranslate">'+esc(m.body)+'</p><time>'+esc(supportDate(m.created_at))+'</time></article>';}).join('')||'<p class="support-empty">'+'Nessun messaggio.'+'</p>';if(atBottom||!messages?.length)box.scrollTop=box.scrollHeight;applyLanguage();}
async function refreshAdminSupport(){if(adminSupportBusy||$('adminDashboard').hidden)return;adminSupportBusy=true;try{const data=await adminApi('/api/admin/support/conversations'),conversations=data.conversations||[];if(activeSupportAccount&&!conversations.some(c=>c.account_id===activeSupportAccount))activeSupportAccount='';$('adminChatConversations').innerHTML=conversations.map(c=>'<button type="button" class="admin-chat-conversation '+(c.account_id===activeSupportAccount?'active':'')+'" data-support-account="'+esc(c.account_id)+'"><b class="notranslate">'+esc(c.account_username)+'</b><small>'+esc(new Date(c.updated_at).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</small></button>').join('')||'<p class="service-note">'+'Nessuna conversazione.'+'</p>';if(activeSupportAccount){const result=await adminApi('/api/admin/support/messages?account_id='+encodeURIComponent(activeSupportAccount));supportAdminMessageMarkup(result.messages||[]);}else{$('adminChatMessages').innerHTML='<p class="service-note">'+'Seleziona una conversazione.'+'</p>';}$('adminChatSend').disabled=!activeSupportAccount;applyLanguage();}catch(error){$('adminChatError').textContent=localizedText(error.message);}finally{adminSupportBusy=false;}}
function startAdminSupportPolling(){if(adminSupportTimer)clearInterval(adminSupportTimer);refreshAdminSupport();adminSupportTimer=setInterval(()=>{if($('adminDashboard').hidden){clearInterval(adminSupportTimer);adminSupportTimer=null;return;}refreshAdminSupport();},4000);}
