$('adminDeposits').innerHTML=ledger(d.deposits);$('adminWithdrawals').innerHTML=ledger(d.withdrawals);
$('adminInvestments').innerHTML=(d.investments||[]).map(i=>'<tr><td>'+esc(i.username)+'</td><td>'+esc(adminMoney(i.amount))+'</td><td>'+esc(i.days)+' giorni</td><td>'+((i.active)?'Registrata attiva':'Conclusa')+'</td></tr>').join('')||'<tr><td colspan="4">Nessun record</td></tr>';
