 $('adminEmailVerifications').innerHTML=(emailVerificationData.requests||[]).map(r=>'<tr><td>'+esc(r.username)+'</td><td>'+esc(r.email)+'</td><td>'+esc({pending:'In attesa',code_sent:'Codice inviato',verified:'Verificata',expired:'Scaduta'}[r.status]||r.status)+'</td><td>'+esc(new Date(r.created_at).toLocaleString(activeLang==='en'?'en-US':'it-IT'))+'</td><td>'+(r.status==='pending'||r.status==='code_sent'?'<button class="admin-action approve" data-email-otp-request="'+esc(r.id)+'">Genera OTP e prepara email</button>':'—')+'</td></tr>').join('')||'<tr><td colspan="5">Nessuna richiesta</td></tr>';
