(async function boot(){if(adminMode){if(localStorage.getItem(ADMIN_VIEW_KEY))showAdminDashboard();else showAdminLogin();return;}const token=localStorage.getItem(TOKEN_KEY);if(token){try{await refresh();enterApp();return;}catch(error){console.warn('Sessione conservata; aggiornamento account non riuscito.',error);}}$('authScreen').hidden=false;$('appBody').hidden=true;$('adminScreen').hidden=true;if(inviteParam){$('tabRegister').click();$('regInvite').value=inviteParam;}})();
// No background polling: refresh data only when the user opens a section or performs an action.
